package com.ayushig.localrag.core.bundle

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Golden bundle for [BundleReaderGoldenTest].
 *
 * Written once by the JVM BundleWriter from the first three chunks of the frozen test corpus
 * (contentVersion 47, builtAt 2026-09-13T10:00:00Z, 4-dimensional vectors), then frozen here so
 * the same bytes are read on every platform, including iOS.
 */
@OptIn(ExperimentalEncodingApi::class)
object GoldenBundleFixture {

    const val BASE64 = ""

    const val NO_MANIFEST_BASE64 = ""

    const val WRONG_VECTORS_BASE64 = ""

    fun bytes(): ByteArray = Base64.decode(BASE64)

    fun noManifestBytes(): ByteArray = Base64.decode(NO_MANIFEST_BASE64)

    fun wrongVectorsBytes(): ByteArray = Base64.decode(WRONG_VECTORS_BASE64)

    const val CONTENT_VERSION = 47
    const val BUILT_AT = "2026-09-13T10:00:00Z"
    const val CHUNK_COUNT = 3
    const val DIMENSIONS = 4

    val CHUNK_IDS = listOf(
        "brokerage-charges#brokerage",
        "brokerage-charges#exchange-and-regulatory-charges",
        "brokerage-charges#where-to-see-what-you-paid",
    )

    /** One row per chunk: [-2.5, 0.125, 0.1, chunkIndex]. */
    val VECTORS = floatArrayOf(
        -2.5f, 0.125f, 0.1f, 0.0f,
        -2.5f, 0.125f, 0.1f, 1.0f,
        -2.5f, 0.125f, 0.1f, 2.0f,
    )

    const val QUERY_1 = "brokerage"
    val QUERY_1_TOP_IDS = listOf(
        "brokerage-charges#brokerage",
        "brokerage-charges#where-to-see-what-you-paid",
        "brokerage-charges#exchange-and-regulatory-charges",
    )

    const val QUERY_2 = "contract note"
    val QUERY_2_TOP_IDS = listOf(
        "brokerage-charges#where-to-see-what-you-paid",
    )

    const val NO_MANIFEST_MESSAGE = "bundle has no manifest.json"
    const val WRONG_VECTORS_MESSAGE =
        "vectors.bin is 4 bytes, expected 48 for 3 chunks at 4 dimensions"
}
